                nums[i], nums[ptr] = nums[ptr], nums[i]
                ptr += 1

impl Solution {
  pub fn sort_colors(nums: &mut Vec<i32>) {
    let n = nums.len();
    let mut ptr = 0;
    for i in 0..n {
      if nums[i] == 0 {
        nums.swap(i, ptr);
        ptr += 1;
      }
    }
    for i in ptr..n {
      if nums[i] == 1 {
        nums.swap(i, ptr);
        ptr += 1;
      }
    }
  }
}

